function buildWorkflowGraph():WorkflowGraph{
 const nodes=state.graph.map((label,i)=>({
  id:"step-"+i,
  kind:i===0?"text" as const:"media.process" as const,
  label,
  inputs:i===0?[]:[{id:"input",label:"Input",type:"any" as const,required:true}],
  outputs:i===state.graph.length-1?[]:[{id:"output",label:"Output",type:"any" as const}],
  config:{}
 }));
 const edges=state.graph.slice(1).map((_,i)=>({
  id:"edge-"+i,
  sourceNodeId:"step-"+i,
  sourcePortId:"output",
  targetNodeId:"step-"+(i+1),
  targetPortId:"input"
 }));
 return {id:"local-workflow",projectId:state.activeProject||"local-project",revision:1,name:"Local draft workflow",nodes,edges};
}
